// TH18 v1.00a st03bs.ecl.txt:190-306, Boss2 non-spell (BossCard1 -> Boss2).
// Source t0 is Boss2 entry; 120-frame shell buffer precedes it. Boss2 waits 90+80,
// then repeats a 240-frame cycle (rank3: 200) with I0 = 20..26 at the cap.
const TIME_LIMIT: int = 1972;
const SOURCE_LIMIT: int = 1850;
const OPENING_BUFFER: int = 120;
const TH18_SHARD: int = 512; // source type10 (radius 2.4), color6

xformdef SHARD_MOTION(eoff: angle, foff: angle) {
    // Source etEx chain: ANIM a1 (sh_dist below), OFFSCREEN 200, then four
    // serial VELTIME records (async=0, same effect blocks the next one).
    // Five handler boundaries in this chain, so 195 approximates source 200.
    offscreen_keep(195);
    // record2: VELTIME60, current direction, 3.2 -> 0.03.
    @60 set_accel((0.03fx-3.2fx)/60fx);
    set_accel(0fx);
    // record3: VELTIME30, aim + E at effect entry, 0.03 -> 2.0.
    set_angle(at_effect(aim_player()+eoff));
    @30 set_accel((2.0fx-0.03fx)/30fx);
    set_accel(0fx);
    // record4: VELTIME30, current direction, 2.0 -> 0.03.
    @30 set_accel((0.03fx-2.0fx)/30fx);
    set_accel(0fx);
    // record5: VELTIME30, aim + F + 5deg*RANDF2 at entry, 0.03 -> 2.4.
    // RANDF2 is a per-bullet spawn sample, as in the source etExSet2 argument.
    set_angle(at_effect(aim_player()+foff));
    turn(at_spawn(((rand(65536)-32768)*910/32768) as angle));
    @30 set_accel((2.4fx-0.03fx)/30fx);
    set_accel(0fx);
    stop_fx();
}

// Source Boss2_at: C rings of C bullets. E/F advance once per ring; D advances
// by one inner step / B. Inner G starts at D and steps 2pi/C.
sub boss2_at(c: int, aoff: angle) {
    var rank: int = global(GVAR_RANK);
    var b: int = 12;
    if rank == 1 { b = 20; }
    if rank >= 2 { b = 25; }

    sh_reset(0);
    sh_sprite(0, TH18_SHARD, 6);
    sh_ring(0, 1);            // etAim mode3: fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, 3.2fx, 0fx);
    sh_dist(0, -12.8fx);      // ANIM a1: -4 * initial speed 3.2

    var d0: angle = rand(65536) as angle; // RANDRAD
    var e0: angle = rand(65536) as angle; // RANDRAD
    for j in 0..b {
        // Source increments E/F/D before the first emission of each ring.
        var e: angle = e0+(((j+1)*65536/b) as angle);
        var f: angle = e+aoff;
        var d: angle = d0+((((j+1)*65536/b)/c) as angle);
        // sh_ring distributes the C directions exactly as source G = D + k*2pi/C.
        sh_count(0, c, 1);
        sh_angle(0, d, 0deg);
        sh_xform(0, SHARD_MOTION(e, f));
        sh_fire(0);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source t0: Boss2 entry at the upstream centre (0,128), stationary setup.
    wait(90); // source wait(90)
    // EffChargePoint3 spawn here is a decorative charge effect.
    wait(80); // source wait(80)
    var i0: int = 20;
    var aoff: angle = 5461 as angle; // source F0 = 0.523599rad = 30deg
    var w: int = 120;
    if global(GVAR_RANK) == 3 { w = 100; }
    loop {
        boss2_at(i0, aoff);
        aoff = -aoff; // source F0 *= -1
        card_wait(w);
        card_move_rand();
        card_wait(w);
        if i0 < 26 { i0 = i0+1; }
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx); // source setHitbox(48,48)
    set_hurtbox(20fx); // source setHurtbox(40,40)
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Training shell: the extra controller stays at (0,0) with body collision off.
// The real boss keeps source judgement and body hitbox.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 20000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}

// TH18 v1.00a Boss2 moveRand(60,4,0.7) recipe.
// moveLimit(0,128,280,96) -> position x[-140,140], y[80,176];
// direction inner zone x[-70,70], y[104,152].
// int0 = next source movement step; fx0/fx1 = logical unit direction.

sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // Source 405b90 = signed unit random * pi; values are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Do not normalize this branch before the source fabs tests.
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad, nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
